import sys
from collections import defaultdict

q = int(sys.stdin.readline())
assignments = {}
priority_count = defaultdict(int)
history = []

for _ in range(q):
    command = sys.stdin.readline().strip().split()
    if command[0] == "set":
        ai, xi = command[1], int(command[2])
        if ai in assignments:
            old_xi = assignments[ai]
            priority_count[old_xi] -= 1
        assignments[ai] = xi
        priority_count[xi] += 1
        history.append(("set", ai, xi))
    elif command[0] == "remove":
        ai = command[1]
        if ai in assignments:
            xi = assignments.pop(ai)
            priority_count[xi] -= 1
            history.append(("remove", ai, xi))
    elif command[0] == "query":
        ai = command[1]
        if ai not in assignments:
            print(-1)
        else:
            xi = assignments[ai]
            count = sum(priority_count[p] for p in priority_count if p < xi)
            print(count)
    elif command[0] == "undo":
        di = int(command[1])
        for _ in range(di):
            if history:
                op, ai, xi = history.pop()
                if op == "set":
                    if assignments[ai] == xi:
                        del assignments[ai]
                    else:
                        assignments[ai] = xi
                    priority_count[xi] -= 1
                    if assignments.get(ai):
                        priority_count[assignments[ai]] += 1
                elif op == "remove":
                    assignments[ai] = xi
                    priority_count[xi] += 1
